func safeAudioFilename(value, fallback string) string {
	name := strings.TrimSpace(value)
	if name == "" {
		name = fallback
	}
	replacer := regexp.MustCompile(`[<>:"/\\|?*\x00-\x1f]`)
	name = replacer.ReplaceAllString(name, "-")
	name = regexp.MustCompile(`(?:\s*-\s*)+`).ReplaceAllString(name, " - ")
	name = regexp.MustCompile(`\s+`).ReplaceAllString(name, " ")
	name = strings.Trim(name, " .-")
	if runes := []rune(name); len(runes) > 180 {
		name = string(runes[:180])
	}
	if name == "" {
		return fallback
	}
	return name
}

func audioExtensionFromURL(rawURL string, opus bool) string {
	if opus {
		return ".opus"
	}
	parsed, err := url.Parse(rawURL)
	path := rawURL
	if err == nil {
		path = parsed.Path
	}
	extension := strings.ToLower(filepath.Ext(path))
	if len(extension) >= 3 && len(extension) <= 6 {
		return extension
	}
	return ".mp3"
}

