func resolveAudioOutputPath(recordingID string, detail map[string]any, audioURL string, output string, outputDir string, opus bool) string {
	if output != "" {
		if info, err := os.Stat(output); err == nil && info.IsDir() {
			outputDir = output
		} else {
			return output
		}
	}
	title := recordingID
	if data := nestedMap(detail, "data"); data != nil {
		if fromDetail := stringField(data, "file_name", "filename", "title"); fromDetail != "" {
			title = fromDetail
		}
	}
	fallback := recordingID
	if len(fallback) > 8 {
		fallback = fallback[:8]
	}
	filename := safeAudioFilename(title, fallback) + audioExtensionFromURL(audioURL, opus)
	if outputDir == "" {
		outputDir = "."
	}
	return filepath.Join(outputDir, filename)
}

